return {["fb01_01"]={["down"]=[[fb01_01a]],["dsc"]=[[这里是金牛武馆的大门，门上牌匾刻着刚劲有力的金牛武馆四字。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb01_01]],["item1"]=[[bfitem2]],["name"]=[[大门]],["permission"]=1,["role1"]=[[fb01r01_1]],["roomBgm"]=[[mache]],["roomBgmRule"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_01b]],["visible"]=1},["fb01_01a"]={["BgmDown"]=1,["dsc"]=[[你走在一条石板路上，前面就是大门了。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb01_01a]],["name"]=[[石路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_01]],["visible"]=1},["fb01_01b"]={["BgmDown"]=1,["down"]=[[fb01_01]],["dsc"]=[[你走在去武馆大院的石板路上。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb01_01b]],["item1"]=[[gzxl]],["name"]=[[石路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_01c]],["visible"]=1},["fb01_01c"]={["BgmDown"]=1,["down"]=[[fb01_01b]],["dsc"]=[[你走在去武馆大院的石板路上。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb01_01c]],["name"]=[[石路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_02]],["visible"]=1},["fb01_02"]={["down"]=[[fb01_01c]],["dsc"]=[[这是个大院子，东西两边都是练武场，不少人在这里习武强身，这里很吵，乱烘烘的，你看见不时有扛着东西的，挑着水的匆匆而过。]],["enterable"]=1,["id"]=[[fb01_02]],["item1"]=[[cg2item1]],["left"]=[[fb01_09]],["name"]=[[武馆大院]],["permission"]=1,["right"]=[[fb01_10]],["role1"]=[[fb01r02_1b]],["role2"]=[[fb01r02_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_03]],["visible"]=1},["fb01_03"]={["down"]=[[fb01_02]],["dsc"]=[[这是个大院子，东西两边都是练武场，不少人在这里习武强身，这里很吵，乱烘烘的，你看见不时有扛着东西的，挑着水的匆匆而过，北面上了台阶就是武馆大厅。]],["enterable"]=1,["id"]=[[fb01_03]],["name"]=[[武馆大院]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_04]],["visible"]=1},["fb01_04"]={["down"]=[[fb01_03]],["dsc"]=[[这里是武馆大厅，正中靠北摆着一张八仙桌，桌上供着关公的神位，旁边放着两个青瓷花瓶，插着几支孔雀翎，墙上写着大大的一个“武”字武馆主人早些年在江湖上闯荡，现洗手隐退。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb01_04]],["left"]=[[fb01_20]],["name"]=[[大厅]],["permission"]=1,["right"]=[[fb01_21]],["role1"]=[[fb01r04_1]],["roomBgm"]=[[huo]],["roomBgmRule"]=1,["spaceTime"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_05]],["visible"]=1},["fb01_05"]={["BgmDown"]=1,["down"]=[[fb01_04]],["dsc"]=[[这是个长廊，通向馆主的卧室，这里静悄悄的，没有什么人来，走廊两边爬满了爬山虎，外面烈日，可是你走在走廊里只觉得一阵清凉。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_05]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb01_06]],["role1"]=[[fb01r05_1]],["role2"]=[[fb01r05_2]],["role3"]=[[fb01r05_3]],["role4"]=[[fb01r05_4]],["stepMusic"]=[[mudiban]],["up"]=[[fb01_07]],["visible"]=1},["fb01_06"]={["BgmDown"]=1,["dsc"]=[[这是武馆馆主的书房，房内很静，几缕阳光从窗外的绿荫中直射进来，屋内靠窗放着一个大书架，显然都是些主人常看的书。墙上高悬着几个大字“少壮不努力，老大徒伤悲”。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_06]],["item1"]=[[fb01item_20]],["item2"]=[[fb01item_16]],["item3"]=[[bfitem3]],["left"]=[[fb01_05]],["name"]=[[书房]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_07"]={["BgmDown"]=1,["down"]=[[fb01_05]],["dsc"]=[[这里是武馆馆主的卧室，房子并不大，很整洁简朴，被子叠的整整齐齐，帐子挂了起来，靠窗边摆了一盆盆景，一张小桌，放着几本书。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_07]],["item1"]=[[fb01item_5]],["name"]=[[馆主卧室]],["permission"]=2,["role1"]=[[fb01r07_1]],["role2"]=[[fb01r07_2]],["role3"]=[[fb01r07_3]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb01_08"]={["dsc"]=[[这是间大大的房子，十分宽阔，不少人在这里汗流浃背的苦练着功夫，地上有一些练武用的工具，墙边摆着一排木人桩。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb01_08]],["name"]=[[西武场]],["permission"]=2,["right"]=[[fb01_09]],["role1"]=[[fb01r08_1]],["role2"]=[[fb01r08_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_12]],["visible"]=1},["fb01_09"]={["dsc"]=[[这是个长廊，通向西练武场，人们急冲冲地走过，不时有人被抬出来，看样子是练功脱力昏倒的。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_09]],["left"]=[[fb01_08]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb01_02]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb01_10"]={["dsc"]=[[这是个长廊，通向东练武场，人来人往的，很是热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_10]],["item1"]=[[fb01r10_1]],["left"]=[[fb01_02]],["name"]=[[长廊]],["permission"]=2,["right"]=[[fb01_11]],["role1"]=[[fb01r10_1]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb01_11"]={["dsc"]=[[这是露天练武场，好多人在这里辛苦的练着，你走在场中，没有人回头看你一眼，都在聚精汇神的练着自己的功夫，地上放着几个练功用具。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb01_11]],["left"]=[[fb01_10]],["name"]=[[东武场]],["permission"]=2,["role1"]=[[fb01r11_1]],["role2"]=[[fb01r11_2]],["role3"]=[[fb01r11_3]],["role4"]=[[fb01r11_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_13]],["visible"]=1},["fb01_12"]={["down"]=[[fb01_08]],["dsc"]=[[这是间大大的房子，十分宽阔，不少人在这里汗流浃背的苦练着功夫，地上有一些练武用的工具，墙边摆着一排木人桩。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb01_12]],["name"]=[[西武场]],["permission"]=2,["role1"]=[[fb01r12_1]],["role2"]=[[fb01r12_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_14]],["visible"]=1},["fb01_13"]={["down"]=[[fb01_11]],["dsc"]=[[这是露天练武场，好多人在这里辛苦的练着，你走在场中，没有人回头看你一眼，都在聚精汇神的练着自己的功夫，地上放着几个练功用具。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb01_13]],["item1"]=[[fb01item_13]],["name"]=[[东武场]],["permission"]=2,["role1"]=[[fb01r13_1]],["role2"]=[[fb01r13_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_17]],["visible"]=1},["fb01_14"]={["down"]=[[fb01_12]],["dsc"]=[[这是个长廊，北面是武馆内的物品房，要在武馆做杂事的人都得去物品房领工具，南边是东练武场。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_14]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_19]],["visible"]=1},["fb01_15"]={["dsc"]=[[这里是武馆内的一个习武堂，堂内一个教头在教着武功，几个新手正在向教头学习功夫，堂子正上方挂着个匾，上面写着“吃得苦中苦，方为人上人”。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_15]],["item1"]=[[tmnpc01a]],["item2"]=[[tmnpc01f]],["name"]=[[习武堂]],["permission"]=2,["role1"]=[[fb01r15_1]],["role2"]=[[fb01r15_2]],["role3"]=[[fb01r15_3]],["role4"]=[[fb01r15_4]],["stepMusic"]=[[mudiban]],["up"]=[[fb01_20]],["visible"]=1},["fb01_16"]={["BgmDown"]=1,["dsc"]=[[这里是武馆内的一个帐房，室内一个帐房先生在这里认真地做着帐。几名新弟子正围着帐房先生，看来是想把积攒下来的钱物存在这里。墙上挂有一个牌子。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_16]],["item1"]=[[fb01item_1]],["name"]=[[账房]],["permission"]=2,["role1"]=[[fb01r16_1]],["role2"]=[[fb01r16_2]],["role3"]=[[fb01r16_3]],["stepMusic"]=[[mudiban]],["up"]=[[fb01_21]],["visible"]=1},["fb01_17"]={["down"]=[[fb01_13]],["dsc"]=[[这是个长廊，北面是武馆内的物品房，要在武馆做杂事的人都得去物品房领工具，南边是东练武场。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_17]],["name"]=[[长廊]],["permission"]=2,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[mudiban]],["up"]=[[fb01_22]],["visible"]=1},["fb01_18"]={["dsc"]=[[这里是武馆内用餐的地方。屋里布置很简单，只摆着几张桌椅几个人在一声不响地吃着。一个厨子在不停的忙碌着。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_18]],["item1"]=[[bfitem1]],["name"]=[[饭厅]],["permission"]=2,["right"]=[[fb01_19]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_19"]={["down"]=[[fb01_14]],["dsc"]=[[你走在一条石板路上，北面过去就是后院了，南面是西练功场，西面传来阵阵饭菜的香气，那里是武馆的饭厅。东面过去是武馆大厅。]],["enterable"]=1,["id"]=[[fb01_19]],["left"]=[[fb01_18]],["name"]=[[石路]],["permission"]=2,["right"]=[[fb01_20]],["role1"]=[[fb01r04_2]],["role2"]=[[fb01r19_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_23]],["visible"]=1},["fb01_20"]={["down"]=[[fb01_15]],["dsc"]=[[你走在一条石板路上，北面和南面都是习武堂，不少人在这里进进出出的，东面是武馆大厅。]],["enterable"]=1,["id"]=[[fb01_20]],["left"]=[[fb01_19]],["name"]=[[石路]],["permission"]=2,["right"]=[[fb01_04]],["role1"]=[[fb01r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_24]],["visible"]=1},["fb01_21"]={["down"]=[[fb01_16]],["dsc"]=[[你走在一条石板路上，从这里往东是物品房，你看见有不少人手里拿着各样的工具，从那边过来，西面是武馆大厅。]],["enterable"]=1,["id"]=[[fb01_21]],["left"]=[[fb01_04]],["name"]=[[石路]],["permission"]=2,["right"]=[[fb01_22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_25]],["visible"]=1},["fb01_22"]={["BgmDown"]=1,["down"]=[[fb01_17]],["dsc"]=[[这是物品房，一个大架子。上面放的整整齐齐，看来这里的管家是很认真负责的，一些人正在跟管物品工具的管家说着什么。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_22]],["item1"]=[[fb01item_2]],["item2"]=[[fb01item_26]],["left"]=[[fb01_21]],["name"]=[[物品房]],["permission"]=2,["right"]=[[fb01_39]],["role1"]=[[fb01r22_1]],["role2"]=[[fb01r22_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_29]],["visible"]=1},["fb01_23"]={["down"]=[[fb01_19]],["dsc"]=[[你走在一条石板路上，一直通向后院，路两旁是些普通的花草，树上的小鸟，不停的叫着。]],["enterable"]=1,["id"]=[[fb01_23]],["name"]=[[石路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb01_27]],["visible"]=1},["fb01_24"]={["down"]=[[fb01_20]],["dsc"]=[[这里是武馆内的一个习武堂，堂内一个教头在教着武功，几个新手正在向教头学习功夫，堂子正上方挂着个匾，上面写着“吃得苦中苦，方为人上人”。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_24]],["item1"]=[[fb01item_30]],["name"]=[[习武堂]],["permission"]=2,["role1"]=[[fb01r24_1]],["role2"]=[[fb01r24_2]],["role3"]=[[fb01r24_3]],["role4"]=[[ever24_1]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb01_25"]={["down"]=[[fb01_21]],["dsc"]=[[这里是武馆内的一个小学堂，堂内阵阵朗朗读书声，一个先生在这里认真的教着，这里放满了桌子和椅子，靠先生那边墙上写了几个大字“少壮不努力，老大徒伤悲”。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_25]],["item1"]=[[fb01item_15]],["item2"]=[[fb01item1000]],["name"]=[[学堂]],["permission"]=2,["role1"]=[[fb01r25_1]],["role2"]=[[bfr25_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_26"]={["dsc"]=[[一进屋，你看见屋内放着几口大缸，好像是装水用的，不过缸似乎都是空的，这里没有一个人，估计仆人都跑了。]],["enterable"]=1,["id"]=[[fb01_26]],["item1"]=[[fb01item_6]],["name"]=[[水房]],["permission"]=2,["right"]=[[fb01_27]],["role1"]=[[fb01r26_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_27"]={["down"]=[[fb01_23]],["dsc"]=[[这里是后院，都是些干活做事的地方，西面是一个水房。人们忙忙碌碌的进出，干着自己的活。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_27]],["left"]=[[fb01_26]],["name"]=[[后院]],["permission"]=2,["right"]=[[fb01_28]],["role1"]=[[fb01r27_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_31]],["visible"]=1},["fb01_28"]={["dsc"]=[[这间屋里叮叮哐哐的，你仔细一看，几个人在劈柴火，屋子特别大，屋子一边堆满了已经锯短的木头，但是另一边劈好的柴火却没有多少。]],["enterable"]=1,["id"]=[[fb01_28]],["item1"]=[[fb01item_3]],["item2"]=[[fb01item_9]],["left"]=[[fb01_27]],["name"]=[[柴房]],["permission"]=2,["role1"]=[[fb01r28_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_29"]={["down"]=[[fb01_22]],["dsc"]=[[这是个长廊，往北通向休息室，南面是物品房，这里静悄悄的，人们走路都也小心翼翼的，怕吵着北面休息室里休息的人。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_29]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[mudiban]],["up"]=[[fb01_33]],["visible"]=1},["fb01_30"]={["dsc"]=[[这里是马房，里面臭烘烘的，养了几十匹马，你看过去，马身上都很脏了，该洗洗了，旁边有个水池，里面有些清水。]],["enterable"]=1,["id"]=[[fb01_30]],["name"]=[[马房]],["permission"]=2,["right"]=[[fb01_31]],["role1"]=[[fb01r30_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_31"]={["BgmDown"]=1,["down"]=[[fb01_27]],["dsc"]=[[这里仍然是后院，西面不时传来马嘶声，你看过去，那里是个马房。]],["enterable"]=1,["id"]=[[fb01_31]],["left"]=[[fb01_30]],["name"]=[[后院]],["permission"]=2,["right"]=[[fb01_32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb01_36]],["visible"]=1},["fb01_32"]={["BgmDown"]=1,["dsc"]=[[一进屋，你就被巨大的轰鸣声吵住了，这里堆了好多长的木头，准备要做柴火用的，但是在送去柴房前先得把长木头锯短成一截截的，才好用斧头劈开。你看见几个人在费力的锯着。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_32]],["item1"]=[[fb01item_23]],["left"]=[[fb01_31]],["name"]=[[木材房]],["permission"]=2,["role1"]=[[fb01r32_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_33"]={["BgmDown"]=1,["down"]=[[fb01_29]],["dsc"]=[[这里是武馆内的卧室，屋子有点点旧，但是打扫的非常干净，一排床铺靠墙摆着，东面过去是一间休息室，不断的有人进去休息或醒后离去。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_33]],["name"]=[[卧室]],["permission"]=2,["right"]=[[fb01_34]],["role1"]=[[fb01r33_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_34"]={["BgmDown"]=1,["dsc"]=[[这里是武馆内的休息室，屋子有点点旧，但是打扫的非常干净，一排床铺靠墙摆着，你悄悄的走过去，找个空铺睡了下来。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_34]],["item1"]=[[fb01item_14]],["left"]=[[fb01_33]],["name"]=[[卧室]],["permission"]=2,["role1"]=[[fb01r34_1]],["role2"]=[[fb01r34_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_35"]={["dsc"]=[[这里是块菜地，由于长期得不到良好的照顾，菜地里杂草丛生，种的菜都长势不好，蔫蔫的，地都荒了。]],["enterable"]=1,["id"]=[[fb01_35]],["item1"]=[[fb01item_7]],["name"]=[[菜地]],["permission"]=2,["right"]=[[fb01_36]],["stepMusic"]=[[nidi]],["visible"]=1},["fb01_36"]={["down"]=[[fb01_31]],["dsc"]=[[这里是后院外了，四周都是菜地，往北是个小山坡，东西面都是用篱笆围起的菜地，种着各样的菜，篱笆很破烂，摇摇欲坠，看来这里没什么人打理。]],["enterable"]=1,["id"]=[[fb01_36]],["item1"]=[[fb01item_21]],["left"]=[[fb01_35]],["name"]=[[后院]],["permission"]=2,["right"]=[[fb01_37]],["role1"]=[[fb01r36_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_37"]={["dsc"]=[[这里是块菜地，菜地旁有几口大缸，里面盛满了水，可是菜地看起来都干裂了，几棵菜蔫蔫的长着，看样子是缺水太多了。]],["enterable"]=1,["id"]=[[fb01_37]],["item1"]=[[fb01item_7]],["left"]=[[fb01_36]],["name"]=[[菜地]],["permission"]=2,["role1"]=[[fb01r37_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_38"]={["dsc"]=[[这是一个大池塘，塘里的水十分寒冷，这种天还是不要轻易下去比较好。]],["enterable"]=1,["id"]=[[fb01_38]],["item1"]=[[fb01item_29]],["name"]=[[池塘]],["permission"]=2,["stepMusic"]=[[luoshui]],["visible"]=1},["fb01_39"]={["dsc"]=[[这是物品房旁边的密室，这里面没什么摆设，且空间狭小，不知是做什么用的。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb01_39]],["left"]=[[fb01_22]],["name"]=[[密室]],["permission"]=2,["role1"]=[[fb01r39_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb01_40"]={["dsc"]=[[位于偏远的郊区，因为年久失修，看起来破破烂烂的，地上有血迹从大门口一直延续到里屋。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb01_40]],["name"]=[[偏僻民宅]],["role1"]=[[fb01r40_1]],["stepMusic"]=[[jiaobu]]},["fb01_41"]={["dsc"]=[[无边无际，混沌一片，似乎能看见什么，但又什么也看不清。]],["id"]=[[fb01_41]],["name"]=[[梦魇]],["role1"]=[[fb01r41_1]],["role2"]=[[fb01r41_2]],["stepMusic"]=[[jiaobu]]},["fb01_42"]={["dsc"]=[[无边无际，混沌一片，似乎能看见什么，但又什么也看不清。]],["id"]=[[fb01_42]],["name"]=[[梦魇]],["role1"]=[[fb01r42_1]],["stepMusic"]=[[jiaobu]]}}00